function ProfileForm({ profile }: { profile: Profile }) {
  const [draft, setDraft] = useState(profile)

  useEffect(() => {
    setDraft(profile)
  }, [profile])

  return <input
    value={draft.displayName}
    onChange={e => setDraft({ ...draft, displayName: e.target.value })}
  />
}

type Session = { name: string };
type Theme = 'light' | 'dark';

const SessionContext = createContext<{
  session: Session | null;
  signOut: () => void;
} | null>(null);

const ThemeContext = createContext<{
  theme: Theme;
  toggle: () => void;
} | null>(null);

function AppProviders({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<Session | null>({ name: 'Ada' });
  const [theme, setTheme] = useState<Theme>('light');
  console.log('render AppProviders');

  return (
    <SessionContext.Provider
      value={{ session, signOut: () => setSession(null) }}
    >
      <ThemeContext.Provider
        value={{ theme, toggle: () => setTheme((t) => (t === 'light' ? 'dark' : 'light')) }}
      >
        {children}
      </ThemeContext.Provider>
    </SessionContext.Provider>
  );
}

const Sidebar = memo(function Sidebar() {
  const { theme, toggle } = useContext(ThemeContext)!;
  console.log('render Sidebar');
  return <button onClick={toggle}>theme: {theme}</button>;
});

const UserBadge = memo(function UserBadge() {
  const { session } = useContext(SessionContext)!;
  console.log('render UserBadge');
  return <span>{session?.name ?? 'guest'}</span>;
});

const Footer = memo(function Footer() {
  console.log('render Footer');
  return <footer>© 2026</footer>;
});

export function Shell() {
  return (
    <AppProviders>
      <Sidebar />
      <UserBadge />
      <Footer />
    </AppProviders>
  );
}
